<?php
require_once __DIR__.'/expenses.php';$id=filter_var($_GET['id']??0,FILTER_VALIDATE_INT);$supplier=$id?query('SELECT * FROM bookkeeping_suppliers WHERE id=?',[$id])->fetch():false;
if(!$supplier){http_response_code(404);echo '<p>구매처를 찾을 수 없습니다.</p>';return;}
$rows=query('SELECT * FROM expenses WHERE supplier_id=? AND voided=0 ORDER BY expense_date DESC,id DESC',[$id])->fetchAll();$receipts=[];foreach(query('SELECT r.* FROM expense_receipts r JOIN expenses e ON e.id=r.expense_id WHERE e.supplier_id=? AND e.voided=0 ORDER BY r.id',[$id])->fetchAll() as $f)$receipts[$f['expense_id']][]=$f;
$sum=['total_cents'=>0,'hst_cents'=>0,'subtotal_cents'=>0];foreach($rows as $r)foreach($sum as $k=>$_)$sum[$k]+=(int)$r[$k];
?>
<div class="toolbar"><a class="button secondary" href="/?page=bookkeeping-suppliers">← 구매처 관리</a></div><section class="panel"><h2><?=e($supplier['name'])?> · 구매처 원장</h2><div class="bookkeeping-sums"><span><?=count($rows)?>건</span><strong>Amount <?=money($sum['total_cents'])?></strong><span>HST <?=money($sum['hst_cents'])?></span><span>Net Amount <?=money($sum['subtotal_cents'])?></span></div><div class="table-wrap"><table><thead><tr><th>구매처 / 날짜</th><th>Amount</th><th>HST</th><th>Net Amount</th><th>영수증보기</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><a href="/?page=expense-edit&id=<?=(int)$r['id']?>"><?=e($supplier['name'])?> · <?=e($r['expense_date'])?></a></td><td><?=money((int)$r['total_cents'])?></td><td><?=money((int)$r['hst_cents'])?></td><td><?=money((int)$r['subtotal_cents'])?></td><td><?php foreach($receipts[$r['id']]??[] as $n=>$f): ?><a class="button secondary" data-receipt-popup href="/?page=expense-receipt-view&id=<?=(int)$f['id']?>" target="_blank" rel="noopener">영수증보기 <?= $n+1 ?></a><?php endforeach ?><?php if(empty($receipts[$r['id']])): ?>없음<?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php if(!$rows): ?><p>기록된 거래가 없습니다.</p><?php endif ?></section>
